int find_first_occurrence(char *haystack,char *needle){int i;int j;if(needle[0]=='\0')return 0;for(i=0;haystack[i]!='\0';i=i+1){j=0;while(needle[j]!='\0'&&haystack[i+j]==needle[j])j=j+1;if(needle[j]=='\0')return i;}return -1;}
